{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Clinafloxacin, the closest analogue sharing the 8-chloro-6-fluoro-quinolone-3-carboxylic acid core and a basic amine substituent, has an absolute oral bioavailability of approximately 90% in volunteers, directly supporting high F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C58"],
      "claim": "Levofloxacin, a zwitterionic fluoroquinolone with a quinolone-3-carboxylic acid and basic amine, approaches 100% absolute oral bioavailability in humans, demonstrating that full ionization and low logD do not preclude high absorption in this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "Moxifloxacin, another zwitterionic fluoroquinolone, has an absolute oral bioavailability of 86–92% in healthy volunteers, reinforcing the class-level pattern of high oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a fluoroquinolone-3-carboxylic acid with a basic amine, closely analogous to clinafloxacin and other fluoroquinolones that consistently show absolute oral bioavailability above 85% in humans. The closest analogue clinafloxacin (F≈90%) and class-wide experimental evidence outweigh the physicochemical prior predicting poor permeability due to ionization.",
  "evidence_gaps": [
    "No direct pharmacokinetic study exists for the exact query molecule; the closest analogue similarity is moderate (Morgan 0.5882).",
    "The influence of the spiro/fluorocyclopropyl substituent on transporter-mediated absorption or efflux is not directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

